+else if (_error is not null)
+{
+    <div class="alert alert-danger">
+        <strong>Error:</strong> @_error
+        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
+    </div>
+}
+else
+{
+    <!-- Stats bar -->
+    <div class="stats-bar d-flex flex-wrap gap-3 mb-3">
+        <span class="badge bg-secondary">Total: @_allTasks.Count</span>
+        <span class="badge bg-primary">To Do: @GetColumnTasks("To Do").Count</span>
+        <span class="badge bg-warning text-dark">In Progress: @GetColumnTasks("In Progress").Count</span>
+        <span class="badge bg-success">Done: @GetColumnTasks("Done").Count</span>
+        <span class="badge bg-danger">Overdue: @_allTasks.Count(t => t.DueDate.Date < DateTime.Today && t.Status != "Done")</span>
+    </div>
+
+    <!-- Search -->
+    <div class="mb-3" style="max-width: 400px;">
+        <input type="text" class="form-control" placeholder="Search tasks by title…"
+               @bind="_searchQuery" @bind:event="oninput" />
+    </div>
+
+    <!-- Columns -->
+    <div class="board-columns d-flex gap-3">
+        @foreach (var column in _columns)
+        {
+            var tasks = GetFilteredColumnTasks(column);
+            var colIndex = Array.IndexOf(_columns, column);
+
+            <div class="board-column flex-fill">
+                <div class="column-header d-flex justify-content-between align-items-center p-2 rounded-top">
+                    <h5 class="mb-0">@column</h5>
+                    <span class="badge bg-light text-dark">@tasks.Count</span>
+                </div>
+
+                <div class="column-body p-2">
+                    @foreach (var task in tasks)
+                    {
+                        <div class="card task-card mb-2">
+                            <div class="card-body p-2">
+                                <h6 class="card-title mb-1">@task.Title</h6>
+                                <p class="card-text mb-1 text-muted small">@task.Assignee</p>
+                                <div class="d-flex justify-content-between align-items-center mb-1">
+                                    <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
+                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                </div>
+                                <div class="d-flex gap-1">
+                                    @if (colIndex > 0)
+                                    {
+                                        <button class="btn btn-sm btn-outline-secondary flex-fill"
+                                                disabled="@_moving"
+                                                @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex - 1])">
+                                            ← Move Left
+                                        </button>
+                                    }
+                                    @if (colIndex < _columns.Length - 1)
+                                    {
+                                        <button class="btn btn-sm btn-outline-secondary flex-fill"
+                                                disabled="@_moving"
+                                                @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex + 1])">
+                                            Move Right →
+                                        </button>
+                                    }
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    @if (_addingToColumn == column)
+                    {
+                        <div class="card mb-2 border-primary">
+                            <div class="card-body p-2">
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Title" @bind="_newTitle" />
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Assignee" @bind="_newAssignee" />
+                                <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                    <option value="High">High</option>
+                                    <option value="Medium">Medium</option>
+                                    <option value="Low">Low</option>
+                                </select>
+                                <input type="date" class="form-control form-control-sm mb-1"
+                                       @bind="_newDueDate" />
+                                <div class="d-flex gap-1">
+                                    <button class="btn btn-sm btn-primary flex-fill"
+                                            disabled="@_saving"
+                                            @onclick="() => SaveNewTaskAsync(column)">
+                                        Save
+                                    </button>
+                                    <button class="btn btn-sm btn-outline-secondary flex-fill"
+                                            @onclick="CancelAdd">
+                                        Cancel
+                                    </button>
+                                </div>
+                            </div>
+                        </div>
+                    }
+                    else
+                    {
+                        <button class="btn btn-sm btn-outline-primary w-100"
+                                @onclick="() => BeginAdd(column)">
+                            + Add Task
+                        </button>
+                    }
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private string? _error;
+    private string _searchQuery = string.Empty;
+
+    // Move state
+    private bool _moving;
+
+    // Add-task form state
+    private string? _addingToColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+    private bool _saving;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasksAsync();
+    }
+
+    private async Task LoadTasksAsync()
+    {
+        _loading = true;
+        _error = null;
+
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetColumnTasks(string status) =>
+        _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredColumnTasks(string status)
+    {
+        var tasks = GetColumnTasks(status);
+        if (!string.IsNullOrWhiteSpace(_searchQuery))
+        {
+            tasks = tasks
+                .Where(t => t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase))
+                .ToList();
+        }
+        return tasks;
+    }
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        _moving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _moving = false;
+        }
+    }
+
+    private void BeginAdd(string column)
+    {
+        _addingToColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd()
+    {
+        _addingToColumn = null;
+    }
+
+    private async Task SaveNewTaskAsync(string column)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        _saving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
+            // If the task was created with a different status than the target column, update it
+            if (created.Status != column)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, column);
+                created = created with { Status = column };
+            }
+            _allTasks.Add(created);
+            _addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

